  "Alle Merkmale": "Toutes les caractéristiques",
  "Festpreis nach dem Erstgespräch.": "Prix fixe après le premier échange.",
  "Bei jeder Leistung dabei": "Inclus dans chaque prestation",
  "Monatlicher Bericht": "Rapport mensuel",
  "Änderungen inklusive": "Modifications incluses",
  "Keine Einarbeitung": "Aucune formation nécessaire",
  "Was das heisst": "Ce que cela signifie",
  "Wer Ihren Agent baut, betreut ihn auch.": "Qui construit votre agent en assure aussi le suivi.",
  "AVV, EU-Verarbeitung, wo verfügbar, Löschfristen nach Ihrer Vorgabe.": "DPA, traitement dans l'UE lorsque c'est possible, durées de conservation selon vos consignes.",
  "Anfragen, Buchungen und gesparte Zeit auf einer Seite.": "Demandes, réservations et temps gagné sur une seule page.",
  "Kleine Anpassungen meist am selben Tag.": "Petits ajustements, le plus souvent le jour même.",
  "Sie bekommen einen fertigen Agent, keine Software.": "Vous recevez un agent prêt à l'emploi, pas un logiciel.",
  "Keine Mindestlaufzeit.": "Sans durée minimale.",
  "Was den Unterschied macht": "Ce qui fait la différence",
  "Termine direkt im Gespräch": "Rendez-vous pris pendant l'échange",
  "Der Agent prüft freie Zeiten und bucht, verschiebt oder storniert Termine direkt in Ihrem Kalender.": "L'agent vérifie les créneaux libres et réserve, déplace ou annule les rendez-vous directement dans votre agenda.",
  "Direkt angebunden: Google Kalender, Cal.com, Calendly und GoHighLevel; Outlook und Branchen-Buchungssysteme über Automation oder Schnittstelle, sofern verfügbar. Bestätigung und Erinnerung per SMS oder E-Mail.": "Connexion directe : Google Agenda, Cal.com, Calendly et GoHighLevel ; Outlook et logiciels de réservation métier via automatisation ou interface, si disponibles. Confirmation et rappel par SMS ou e-mail.",
  "Antworten aus Ihren Inhalten": "Des réponses tirées de vos contenus",
  "Der Agent beantwortet Fragen mit Ihrer Website, Preisliste und Ihren Dokumenten, statt zu raten.": "L'agent répond à partir de votre site, de votre grille tarifaire et de vos documents, au lieu de deviner.",
  "Plattformwerte: bis 500 Webseiten mit automatischem Einlesen, 25 Dateien à 50 MB (PDF, Word, Excel, Bilder u. a.) und eigene Textbausteine. Tabellen und Überschriften werden sauber zerlegt, der Abruf ist im Transkript sichtbar, und Wissensdatenbanken lassen sich einzelnen Gesprächsschritten zuweisen.": "Valeurs de la plateforme : jusqu'à 500 pages web importées automatiquement, 25 fichiers de 50 Mo (PDF, Word, Excel, images, etc.) et vos propres blocs de texte. Tableaux et titres sont proprement découpés, la consultation est visible dans la transcription, et les bases de connaissances peuvent être attribuées à certaines étapes de l'échange.",
  "Mehrsprachig mit automatischer Erkennung": "Multilingue avec détection automatique",
  "Der Agent erkennt die Sprache Ihrer Kunden und antwortet darin, natürlich auch auf Deutsch.": "L'agent reconnaît la langue de vos clients et y répond, en français bien sûr.",
  "Plattformwert: 55 Sprachen, darunter Deutsch, Französisch, Italienisch und Englisch. Sprachen sind pro Agent einzeln wählbar, ein Sprachwechsel mitten im Gespräch ist mit passenden Erkennungsanbietern möglich; einsprachige Agenten erkennen am genauesten.": "Valeur de la plateforme : 55 langues, dont le français, l'allemand, l'italien et l'anglais. Les langues se choisissent par agent ; un changement de langue en cours d'échange est possible avec les fournisseurs de reconnaissance adaptés ; les agents monolingues sont les plus précis.",
  "Erinnert sich an Stammkunden": "Se souvient des clients fidèles",
  "Meldet sich ein Kunde erneut, weiss der Agent, worum es beim letzten Mal ging.": "Quand un client revient, l'agent sait de quoi il était question la dernière fois.",
  "Kurzakte pro Kontakt (bis 2.000 Zeichen) wird nach Anrufen und SMS-Chats fortgeschrieben und ist für mehrere Agenten lesbar; bekannte Angaben müssen nicht neu erfragt werden. Die Speicherung lässt sich abschalten.": "Une fiche courte par contact (jusqu'à 2 000 caractères) est complétée après les appels et les échanges SMS, et lisible par plusieurs agents ; les informations connues n'ont pas à être redemandées. La mémorisation peut être désactivée.",
  "Haben Sie Freitag noch etwas frei?": "Auriez-vous encore un créneau vendredi ?",
  "Ja, um 10:00 oder 15:30 Uhr. Was passt Ihnen?": "Oui, à 10 h ou à 15 h 30. Qu'est-ce qui vous convient ?",
  "Kalender · Fr 15:30 gebucht": "Agenda · ven. 15 h 30 réservé",
  "Was kostet eine Gesichtsbehandlung?": "Combien coûte un soin du visage ?",
  "Die klassische Behandlung kostet {{m:95}} und dauert 60 Minuten.": "Le soin classique coûte {{m:95}} et dure 60 minutes.",
  "Quelle · Preisliste.pdf": "Source · Grille-tarifaire.pdf",
  "Aus Ihrer Preisliste": "Tiré de votre grille tarifaire",
  "Do you have a room for two nights?": "Do you have a room for two nights?",
  "Yes, from Friday. Shall I hold a double room for you?": "Yes, from Friday. Shall I hold a double room for you?",
