  "Anrufer erkennen, Tickets suchen, aktualisieren und anlegen, öffentliche Antworten oder interne Notizen schreiben.": "Identifier les appelants, rechercher, mettre à jour et créer des tickets, rédiger des réponses publiques ou des notes internes.",
