  "Google Search Console": "Google Search Console",
  "Freie Zeiten aus Ihrem Kalender, zwei Klicks zur Buchung, Bestätigung per SMS oder E-Mail.": "Créneaux libres issus de votre agenda, réservation en deux clics, confirmation par SMS ou e-mail.",
  "Online-Terminbuchung": "Prise de rendez-vous en ligne",
  "Chat Agent, Sprechen im Browser und Rückruf-Knopf sind von Anfang an eingebaut.": "Chat Agent, conversation vocale dans le navigateur et bouton de rappel sont intégrés d'emblée.",
