  "Kontaktformulare": "Formulaires de contact",
  "Automatisierung & Workflows": "Automatisation & workflows",
  "Ereignisse in Ihren Programmen starten Anrufe, und Ergebnisse fliessen automatisch zurück.": "Des événements dans vos logiciels déclenchent des appels, et les résultats y reviennent automatiquement.",
  "App-Ereignisse starten Anrufe; Transkripte, Zusammenfassungen und Ergebnisse gehen an tausende Apps.": "Des événements d'apps déclenchent des appels ; transcriptions, résumés et résultats sont transmis à des milliers d'apps.",
  "Zapier": "Zapier",
  "Visuelle Szenarien verzweigen nach Gesprächsergebnis und arbeiten Anruflisten ab.": "Des scénarios visuels se ramifient selon le résultat de l'appel et traitent des listes d'appels.",
