  "Kumulierter Nutzen und Kosten über 12 Monate": "Bénéfice et coûts cumulés sur 12 mois",
  "Annahmen: 4,33 Wochen pro Monat, 8-Stunden-Arbeitstag. Kosten mit der einmaligen Einrichtung am unteren Ende der Spanne (Voice {{p:voice-agent.setupMin}}, Chat {{p:chatbot.setupMin}}, Social {{p:social-media.setupMin}}) plus laufende Kosten: beim Voice Agent {{p:voice-agent.monthly}} Grundgebühr pro Monat und 4 Gesprächsminuten pro Anruf zu {{p:voice-agent.perUnit}}, 14 Nachrichten pro Chat und 40 Nachrichten pro Social-Media-Stunde zu je {{p:chatbot.perUnit}}. Gerettete Aufträge rechnen wir vorsichtig: nur unbeantwortete Anrufe, davon 30 % mit Abschluss, und nur wenn der Voice Agent ausgewählt ist. Alle Werte sind Schätzungen und keine Garantie.": "Hypothèses : 4,33 semaines par mois, journée de travail de 8 heures. Coûts avec la mise en place unique au bas de la fourchette (Voice {{p:voice-agent.setupMin}}, Chat {{p:chatbot.setupMin}}, Social {{p:social-media.setupMin}}) plus les coûts courants : pour le Voice Agent, {{p:voice-agent.monthly}} d'abonnement de base par mois et 4 minutes d'appel par appel à {{p:voice-agent.perUnit}}, 14 messages par chat et 40 messages par heure de réseaux sociaux à {{p:chatbot.perUnit}} chacun. Nous estimons les commandes sauvées avec prudence : uniquement les appels sans réponse, dont 30 % aboutissent, et seulement si le Voice Agent est sélectionné. Toutes les valeurs sont des estimations, sans garantie.",
