  "Hinter einem Anruf": "Derrière un appel",
  "Was passiert, während Sie arbeiten": "Ce qui se passe pendant que vous travaillez",
  "Ein Anruf geht ein, niemand hat die Hände frei — so nimmt der Agent ihn an, Schritt für Schritt.": "Un appel arrive, personne n'a les mains libres : voici comment l'agent le prend en charge, étape par étape.",
  "Anrufverlauf": "Déroulé de l'appel",
  "Gerne — Sie sind am Donnerstag um 14:15 Uhr bei Mira eingetragen. Die Bestätigung kommt gleich per SMS.": "Avec plaisir. Vous êtes inscrite jeudi à 14 h 15 chez Mira. La confirmation arrive par SMS.",
  "Angenommen": "Décroché",
  "Beim ersten Klingeln, auch abends und am Wochenende — kein Besetztzeichen, keine Mailbox.": "Dès la première sonnerie, y compris le soir et le week-end. Ni tonalité occupée, ni messagerie.",
  "Verstanden": "Compris",
  "Die Anruferin möchte einen Termin für Schnitt und Farbe, am liebsten diese Woche.": "L'appelante souhaite un rendez-vous coupe et couleur, idéalement cette semaine.",
  "Gebucht": "Réservé",
