  "Beispielwerte · ein Kosmetikstudio, acht Wochen": "Valeurs d'exemple · un institut de beauté, huit semaines",
  "Hinter einer Chat-Nachricht": "Derrière un message de chat",
  "Jede Antwort mit Quelle": "Chaque réponse avec sa source",
  "Was der Chatbot zwischen der Frage und der Antwort auf Ihrer Website tut.": "Ce que fait le chatbot sur votre site, entre la question et la réponse.",
  "Antwortverlauf": "Déroulé de la réponse",
  "Ja, sonntags sind wir von 9 bis 14 Uhr da. Für wie viele Personen darf ich reservieren?": "Oui, le dimanche nous sommes ouverts de 9 h à 14 h. Pour combien de personnes souhaitez-vous réserver ?",
  "Gelesen": "Lu",
  "„Habt ihr am Sonntag offen und kann ich reservieren?“ — zwei Fragen in einer.": "« Vous êtes ouverts dimanche et je peux réserver ? » : deux questions en une.",
  "Gesucht": "Recherché",
  "Öffnungszeiten und Reservierungsregeln auf Ihrer Website gefunden.": "Horaires d'ouverture et conditions de réservation trouvés sur votre site.",
  "Belegt": "Étayé",
  "Antwort aus diesen Seiten zusammengesetzt. Fehlt etwas, fragt er nach statt zu raten.": "Réponse composée à partir de ces pages. S'il manque une information, il pose la question au lieu de deviner.",
  "Übergeben": "Transmis",
  "Reservierungswunsch mit Name und Uhrzeit an Ihr Postfach weitergeleitet.": "Demande de réservation transmise à votre boîte mail, avec nom et heure.",
  "Antworten mit Quelle": "Réponses avec source",
  "Beispielwerte · der Rest stellte eine Rückfrage statt zu raten": "Valeurs d'exemple · pour le reste, une question de précision plutôt qu'une supposition",
  "Hinter einem Kommentar": "Derrière un commentaire",
  "Antworten, bevor der Feed weiterscrollt": "Répondre avant que le fil ne défile",
  "Was die Social Media AI mit einem neuen Kommentar und dem Redaktionsplan macht.": "Ce que fait Social Media AI d'un nouveau commentaire et du calendrier éditorial.",
  "Social-Verlauf": "Historique réseaux sociaux",
  "Ja, ein paar Plätze sind noch frei! Ich schicke Ihnen den Link zur Buchung per Nachricht.": "Oui, il reste encore quelques places ! Je vous envoie le lien de réservation en message privé.",
  "Erkannt": "Repéré",
  "Neuer Kommentar unter dem Reel: „Habt ihr noch Termine vor Weihnachten?“": "Nouveau commentaire sous le Reel : « Vous avez encore des créneaux avant Noël ? »",
  "Geprüft": "Vérifié",
  "Ton freundlich, keine Beschwerde — direkte Antwort ist freigegeben.": "Ton amical, pas de réclamation : réponse directe autorisée.",
  "Beantwortet": "Répondu",
  "Antwort mit Link zur Buchung veröffentlicht, Direktnachricht angeboten.": "Réponse publiée avec le lien de réservation, message privé proposé.",
  "Eingeplant": "Planifié",
  "Nächster Post für Freitag, 18 Uhr, im Redaktionsplan hinterlegt.": "Prochaine publication prévue vendredi à 18 h dans le calendrier éditorial.",
  "Kommentare in unter 5 Min. beantwortet": "Commentaires traités en moins de 5 min",
