  "Hinter einer Anfrage": "Derrière une demande",
  "Was der Agent wusste, bevor er antwortete": "Ce que l'agent savait avant de répondre",
  "Der Kalender, den er geöffnet hat, die Regel, die er geprüft hat, und was er selbst erledigen durfte.": "L'agenda qu'il a consulté, la règle qu'il a vérifiée et ce qu'il était autorisé à faire seul.",
  "Anfrageverlauf": "Déroulé de la demande",
  "Erledigt — ich habe es für Sie eingetragen, die Bestätigung kommt gleich.": "C'est fait : je l'ai inscrit pour vous, la confirmation arrive dans un instant.",
  "Kunde erkannt": "Client identifié",
  "Über die Telefonnummer zugeordnet, letzter Besuch und offene Termine geladen.": "Reconnu grâce au numéro de téléphone ; dernière visite et rendez-vous à venir chargés.",
  "Kalender gelesen": "Agenda consulté",
  "Live-Verfügbarkeit statt einer veralteten Liste.": "Disponibilités en temps réel plutôt qu'une liste périmée.",
  "Regel angewendet": "Règle appliquée",
  "Ihre Stornoregel wörtlich zitiert, nicht frei umschrieben.": "Vos conditions d'annulation citées mot pour mot, sans paraphrase.",
  "Erledigt": "Terminé",
  "Änderung eingetragen und im selben Gespräch bestätigt.": "Modification enregistrée et confirmée au cours du même appel.",
  "Vollständig selbst erledigt": "Entièrement traité en autonomie",
  "Beispielwerte · der Rest geht mit vollem Kontext an Ihr Team": "Valeurs d'exemple · le reste est transmis à votre équipe avec tout le contexte",
  "Hinter einem verpassten Anruf": "Derrière un appel manqué",
  "Was eine unbeantwortete Anfrage kostet": "Ce que coûte une demande sans réponse",
  "Warum sich ein Agent meist schon mit wenigen zusätzlichen Buchungen im Monat trägt.": "Pourquoi un agent est souvent rentabilisé avec quelques réservations de plus par mois.",
  "Rechenweg": "Le calcul",
  "Guten Abend! Wir haben zwar schon geschlossen, aber ich kann Ihnen gleich einen Termin eintragen.": "Bonsoir ! Nous sommes déjà fermés, mais je peux vous réserver un rendez-vous tout de suite.",
  "Anruf verpasst": "Appel manqué",
  "Freitag, 18:40 Uhr — das Team ist mitten in der Arbeit oder schon zu Hause.": "Vendredi, 18 h 40 : l'équipe est en plein travail ou déjà rentrée.",
  "Kunde sucht weiter": "Le client cherche ailleurs",
  "Die meisten rufen nicht ein zweites Mal an, sondern beim nächsten Anbieter.": "La plupart ne rappellent pas : ils contactent le prestataire suivant.",
  "Mit Norra wird die Anfrage sofort beantwortet und eingetragen.": "Avec Norra, la demande reçoit une réponse immédiate et est enregistrée.",
  "Umsatz gesichert": "Chiffre d'affaires préservé",
  "Der Termin bleibt bei Ihnen — und mit ihm der Umsatz.": "Le rendez-vous reste chez vous, et le chiffre d'affaires avec lui.",
  "Anfragen gesichert": "Demandes préservées",
  "Richtwerte · hängt von Branche und Anrufvolumen ab": "Valeurs indicatives · selon le secteur et le volume d'appels",
  "Ein Ablauf, drei Kanäle": "Un processus, trois canaux",
  "Telefon, Website und Social Media aus einer Hand": "Téléphone, site web et réseaux sociaux : un seul interlocuteur",
  "Welche Anfrage auch hereinkommt — die Agenten arbeiten mit demselben Wissen über Ihren Betrieb.": "Quelle que soit la demande, les agents s'appuient sur la même connaissance de votre entreprise.",
  "Kanalverlauf": "Historique des canaux",
  "Gerne! Ich habe Ihnen den Termin eingetragen und die Bestätigung geschickt.": "Avec plaisir ! J'ai inscrit votre rendez-vous et vous ai envoyé la confirmation.",
  "Ein Anruf, eine Chat-Nachricht oder ein Kommentar unter Ihrem Post.": "Un appel, un message de chat ou un commentaire sous votre publication.",
  "Preise, Öffnungszeiten und Regeln aus Ihrer Wissensdatenbank.": "Tarifs, horaires et règles issus de votre base de connaissances.",
