  "Termin eintragen, Reservierung weitergeben oder freundlich antworten.": "Inscrire un rendez-vous, transmettre une réservation ou répondre aimablement.",
  "Übersicht": "Vue d'ensemble",
  "Alles landet im selben Verlauf — Sie sehen, was erledigt wurde.": "Tout arrive dans le même historique : vous voyez ce qui a été fait.",
  "Anfragen ohne Wartezeit beantwortet": "Demandes traitées sans attente",
