  "Wenige Schritte, bis Ihr Agent die erste Anfrage beantwortet.": "Quelques étapes avant que votre agent ne réponde à sa première demande.",
  "Hallo, hier ist Lina vom Studio Belle. Wie kann ich Ihnen helfen?": "Bonjour, Studio Belle, Lina à l'appareil. Que puis-je faire pour vous ?",
  "Wir klären in rund 20 Minuten, welcher Agent zu Ihrem Betrieb passt.": "En 20 minutes environ, nous déterminons quel agent convient à votre entreprise.",
  "Bau": "Conception",
  "Wir schreiben die Gesprächsführung, hinterlegen Ihr Wissen und verbinden Ihre Systeme.": "Nous rédigeons le scénario de conversation, intégrons vos connaissances et connectons vos systèmes.",
