  "Klingt wie ein guter Empfang": "Un accueil digne de ce nom",
  "Natürlicher Sprecherwechsel, kurze Antwortzeit und menschlicher Ton lassen Kunden normal sprechen statt Tasten zu drücken.": "Tours de parole naturels, réponses rapides et ton humain : vos clients parlent normalement au lieu de taper sur des touches.",
  "Immer erreichbar": "Toujours joignable",
  "Kein Klingeln ins Leere, auch nachts, am Wochenende und wenn mehrere gleichzeitig anrufen.": "Plus d'appel dans le vide, même la nuit, le week-end ou quand plusieurs personnes appellent en même temps.",
  "Hinter jedem Norra-Agenten steckt ein KI-Modell, das Sie nicht selbst aussuchen müssen, aber können: Wir wählen pro Aufgabe das passende Modell, auf Wunsch pro Gesprächsschritt, oder binden Ihr eigenes an.": "Chaque agent Norra repose sur un modèle IA que vous n'avez pas à choisir, mais que vous pouvez choisir : nous retenons le modèle adapté à chaque tâche, au besoin à chaque étape de la conversation, ou connectons le vôtre.",
