  "Optional": "Facultatif",
  "Annahmen: 4,33 Wochen pro Monat, 8-Stunden-Arbeitstag. Kosten mit der einmaligen Einrichtung am unteren Ende der Spanne (Voice {{p:voice-agent.setupMin}}, Chat {{p:chatbot.setupMin}}, Social {{p:social-media.setupMin}}) plus laufende Kosten: beim Voice Agent {{p:voice-agent.monthly}} Grundgebühr pro Monat und 4 Gesprächsminuten pro Anruf zu {{p:voice-agent.perUnit}}, 14 Nachrichten pro Chat und 40 Nachrichten pro Social-Media-Stunde zu je {{p:chatbot.perUnit}}.": "Hypothèses : 4,33 semaines par mois, journée de travail de 8 heures. Coûts calculés avec la mise en place unique au bas de la fourchette (Voice {{p:voice-agent.setupMin}}, Chat {{p:chatbot.setupMin}}, Social {{p:social-media.setupMin}}), plus les coûts courants : pour le Voice Agent, {{p:voice-agent.monthly}} d'abonnement de base par mois et 4 minutes d'appel par appel à {{p:voice-agent.perUnit}} ; 14 messages par chat et 40 messages par heure de réseaux sociaux à {{p:chatbot.perUnit}} chacun.",
  "Gerettete Aufträge rechnen wir vorsichtig: nur unbeantwortete Anrufe, davon 30 % mit Abschluss, und nur wenn der Voice Agent ausgewählt ist. Alle Werte sind Schätzungen und keine Garantie.": "Nous estimons prudemment les commandes sauvées : uniquement les appels sans réponse, dont 30 % aboutissent, et seulement si le Voice Agent est sélectionné. Toutes les valeurs sont des estimations, sans garantie.",
  "Norra-Website": "Site web Norra",
  "Datum": "Date",
  "Hinweis für den Betreiber: Vorlage, keine Rechtsberatung. Alle markierten Platzhalter ausfüllen,": "Note à l'exploitant : modèle, pas un conseil juridique. Remplissez tous les champs marqués,",
  "nicht zutreffende Abschnitte streichen und den Text vor der Veröffentlichung rechtlich prüfen lassen": "supprimez les sections non applicables et faites vérifier le texte par un juriste avant publication",
  "(Schweiz: revDSG, UWG Art. 3 Abs. 1 lit. s; Deutschland/EU: DSGVO, DDG § 5, MStV § 18).": "(Suisse : nLPD, LCD art. 3, al. 1, let. s ; Allemagne/UE : RGPD, DDG § 5, MStV § 18).",
  "Empfehlung: Google Fonts lokal einbinden, dann den Abschnitt Schriftarten anpassen.": "Recommandation : intégrer Google Fonts en local, puis adapter la section Polices.",
  "Unterauftragsverarbeiter der Agent-Plattform und des Formulardienstes aktuell halten.": "Tenir à jour la liste des sous-traitants de la plateforme d'agents et du service de formulaires.",
